insert into knowledge (id, src, school, cat, lv, weight, tags, body) values
  ('X1', '嶋石', '二者共通', 'principle', NULL, 'any', '{}'::text[], 'こちらからアドバイスはしない。行動は本人の中から出てくるもの。現時点の情報だけで助言しても「できてたらもうやってるし」となる。'),
  ('X2', '嶋石', '二者共通', 'principle', NULL, 'any', '{}'::text[], '話せたこと自体をまず評価する。誰にも言えないと思っていたのに、よくここで言えたね、と返す。'),
  ('X3', '嶋石', '二者共通', 'principle', NULL, 'any', '{}'::text[], '依存の対象にならないよう境界を保つ。全部を引き受けるわけにもいかないし、友達でも親でもない。相談を受ける者と相談する人という一線を持つ。'),
  ('X4', '嶋石', '二者共通', 'principle', NULL, 'any', '{}'::text[], '急がない。無理に話させない。話しに来ても嫌じゃなかったな、と思って帰ってもらえればその日はそれでいい。'),
  ('X5', '嶋石', '二者共通', 'principle', NULL, 'any', '{}'::text[], '相手が主体。こちらが全部やってあげるわけではない。本人が自分で喋って自分で気づいていくのを支える。'),
  ('IS1', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '受け止めることと同調することは違う。何も考えずに同調してしまうのはリスク。「あいつが悪いんだ」に「あの人悪いよね」とは同調しない。'),
  ('IS2', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '同調すると一面でしか物事を見られなくなり、視野が狭くなる。カウンセリングは逆で、できるだけ視野を広げてもらうのが目的。'),
  ('IS3', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '都合のいい情報だけが返ってくるエコーチェンバーの方向へ行かないようにする。別の角度からも見られるように振り返ってもらう。'),
  ('IS4', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '会話を続ける努力はこちら側に求められる。一言で終わらせない。「そうなの」の次にもう一言ほしい。'),
  ('IS5', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '専門用語は前に出さない。説得力を持たせたいとき以外は使わない。前に出すと受け手がしんどくなる。'),
  ('IS6', '石', '人間性心理学ベース・折衷', 'principle', NULL, 'any', '{}'::text[], '守秘義務を守る。ただし、いのちに関わる話になったときは本人に断ったうえで学校につなぐ。'),
  ('P1', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], '「私がこの人をなんとかしてあげなくては」という万能感を持たない。'),
  ('P2', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], 'どんな話を持ってきた人でも、年齢や状況に関係なく、人として尊ばれる存在として接する。'),
  ('P3', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], '「よくぞ来てくださいました」という気持ちを常に持つ。それで相手が引き出しを開けるか閉めるかが決まる。'),
  ('P5', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], 'ゴールは完結ではなく to be continued。バトンを次の誰かに渡せることが役割。'),
  ('P8', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], '役割は敷居を下げること。人と繋がるのを怖がらなくていい、と背中を押す。'),
  ('P9', '嶋', '来談者中心寄り', 'principle', NULL, 'any', '{}'::text[], '「このタイプの人にはこれ」という先入観で区切らない。'),
  ('R1', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '受容とは説き伏せる態度ではなく、相手の「そうせざるを得ない何か」に配慮しながら丁寧に聴こうとする態度。共感は感情をくみ取り理解し、それを示すこと。'),
  ('R2', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '支援者側の一方的な決めつけが最も警戒すべきリスク。関係ができていない段階では、表層の言葉は本当に相談したいことの何段階か手前にすぎないことがある。'),
  ('R3', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], 'ミスマッチは相談した側の責任ではない。不十分に表出された内容を主訴と決めつけた判断のほうが問題。'),
  ('R4', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '無知の知。相手について自分は何も知らないと自覚し、必要なことは相手から教えてもらう。'),
  ('R5', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '相談する側は一段低い位置に立たされやすい。この壁を越えないと機能しない。相手への敬意が土台。'),
  ('R6', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '限界の自覚。どんな相手でもうまくいくという不健全な万能感を持たず、現実的な有用感を持つ。'),
  ('R7', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '内的準拠枠。その人が認知している世界がその人にとっての現実であり、その全体は本人にしか知り得ない。'),
  ('M5', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '自律・協働・喚起。こちらが与えるのではなく、本人の中にすでに在る力を顕在化するきっかけを起こす。'),
  ('S6', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '解決のエキスパートは本人。こちらが解決の在り方を指し示す立場ではない。'),
  ('CB3', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], 'マイナスの考えをプラスに変えることではなく、その考えにとらわれないこと、考えのレパートリーと柔らかさを取り戻すことを目指す。'),
  ('NA3', '理', '文献（複数流派）', 'principle', NULL, 'any', '{}'::text[], '無知の姿勢。その人の内的世界の専門家は本人だとして教えてもらう。好奇心を持ち続ける。'),
  ('G1', '石', '人間性心理学ベース・折衷', 'ng', 3, 'any', '{}'::text[], '「別に一人でもいいじゃん」のように、本人の困りを問題でないことにする言い方は絶対にしない。'),
  ('G2', '石', '人間性心理学ベース・折衷', 'ng', 3, 'any', '{}'::text[], '「いつでも、いくらでも」は絶対に言わない。無制限に開いていると伝えると境界線が曖昧になる。'),
  ('G3', '石', '人間性心理学ベース・折衷', 'ng', 3, 'any', '{}'::text[], '相手を悪者にすることに同調しない。「あの人ひどいね」と一緒に断じない。'),
  ('G4', '石', '人間性心理学ベース・折衷', 'ng', 3, 'any', '{}'::text[], '「あなたは悪くないよ」とむやみに言わない。事実を確かめないまま免罪すると、視野が狭くなる。'),
  ('N1', '嶋', '来談者中心寄り', 'ng', 3, 'any', '{}'::text[], '「そうは言わんと頑張りな」式の、もっと頑張れという励ましは使わない。相談してくる人はすでにやれる限りを試している。'),
  ('N4', '嶋', '来談者中心寄り', 'ng', 3, 'any', '{}'::text[], '分類に当てはめない。診断名を告げない。当てはめようとすると目の前の人が見えなくなる。'),
  ('N5', '嶋', '来談者中心寄り', 'ng', 3, 'any', '{}'::text[], '必ず良くなる、大丈夫、といった断定的な保証をしない。'),
  ('G5', '石', '人間性心理学ベース・折衷', 'ng', 2, 'any', '{}'::text[], 'いきなりのアドバイスは避ける。「積極的に話しかけてみなよ」「先生に相談してみたら」を最初から言わない。'),
  ('G6', '石', '人間性心理学ベース・折衷', 'ng', 2, 'any', '{}'::text[], '専門用語や技法の名前を出すのは避ける。受け手がしんどくなる。'),
  ('N2', '嶋', '来談者中心寄り', 'ng', 2, 'any', '{}'::text[], '前に聞いた話を初めて聞いたかのように扱わない。忘れられたという寂しさを生む。'),
  ('N3', '嶋', '来談者中心寄り', 'ng', 2, 'any', '{}'::text[], 'ポロッと出た言葉に興味本位で踏み込まない。本人が今は触りたくないものもある。'),
  ('N6', '理', '文献（複数流派）', 'ng', 2, 'any', '{}'::text[], '求められた情報に即応することが、かえって依存を高めたり主体性の伸長と相反することがある。教えたい欲求は、一段上でいたい願望を満たす罠にもなる。'),
  ('G7', '石', '人間性心理学ベース・折衷', 'ng', 1, 'any', '{}'::text[], '「相談したいことがあるから話してきたんでしょう？」は、間違いではないが少し威圧感がある。'),
  ('G8', '石', '人間性心理学ベース・折衷', 'ng', 1, 'any', '{}'::text[], '「あ、そうなん」だけで終えるのは、悪くはないが会話が続かなくなる。次の一言を添える。'),
  ('N7', '理', '文献（複数流派）', 'ng', 1, 'any', '{}'::text[], '適切な査定と妥当な提案でも、頭ではわかっているがうまくいかない人には正論にしかならない。'),
  ('V1', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'rapport', ARRAY['別に','相談したいことがある','なんとなく','特にない']::text[], '「別に相談したいことがあるわけじゃない」には → 「あ、別に相談じゃなくてもいいですよ」と返す。話しかけてきてくれている以上は何か話したいことがあるはずなので、扉を開けたままにする。'),
  ('T21', '嶋', '来談者中心寄り', 'ask', NULL, 'rapport', ARRAY['言われた','来させられ','嫌々','親に','先生に']::text[], '嫌々来た様子があるときは「今日ここに来たのはどういう経緯で？」「誰に行けと言われたの？」と聞き、背景の鬱憤をまず喋ってもらう。'),
  ('V6', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'rapport', ARRAY['うん','わかんない','わからない','別に','そうですね','はい']::text[], '短文や相槌だけのときは → 「そっか、わかんないかー」と受けて、「そのことについてもう少し話したかったら話してもいいし、別の話題がよければ別でもいいし」と選べる形で返す。'),
  ('V7', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'rapport', ARRAY['うん','わかんない','話したくない','めんどい']::text[], '無理に話させても仕方ないので、雑談に切り替えることもある。「今クラスで何が流行ってるの？」など、どうでもいい話をする。'),
  ('IS7', '石', '人間性心理学ベース・折衷', 'stance', NULL, 'rapport', '{}'::text[], '本当に話したくない日は、一緒に折り紙だけして終わる日もある。そうしているうちに「実はな」が出てくることもある。そんなに急がない。'),
  ('T13', '嶋', '来談者中心寄り', 'read', NULL, 'rapport', '{}'::text[], 'こちらの意見を受け止める余裕がなさそうだと感じたら、まだ聞く段階。それ自体が見立ての手がかり。'),
  ('T12', '嶋', '来談者中心寄り', 'stance', NULL, 'rapport', ARRAY['わかってくれない','誰も','なんで','ずっと','いつも']::text[], '思いでいっぱいの人にはこちらの言葉が入る隙間がない。まず「こんなにやってるのに」を聞かせてもらう。'),
  ('V2', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'main', ARRAY['居場所','クラス','なんとなく','感じ','孤独','ぼっち']::text[], '「居場所がない感じがする」には → 「もうちょっと詳しく教えて」「居場所がない感じって、どんな時に感じるの？」と、感じている場面を具体化してもらう。'),
  ('V3', '石', '人間性心理学ベース・折衷', 'resp', NULL, 'main', ARRAY['居場所','わからない','言えない','うまく言えない','もやもや']::text[], '感じ方を別の言葉に置き換えてもらう。選択肢を並べると答えやすい。寂しいのか、話しかけたいのに言葉が出なくてもどかしいのか、誰にも注目されていない孤独感なのか、グループができていてどこに入っていいかわからないのか。'),
  ('V4', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'main', ARRAY['せいで','あの子','悪い','ひどい','変わってくれない']::text[], '「全部あの子のせい」には → 同調も否定もせず「そう感じるエピソードがあったの？」「何をきっかけにそう感じるようになったの？」と、出来事を聞く。'),
  ('V5', '石', '人間性心理学ベース・折衷', 'verbatim', NULL, 'main', ARRAY['せいで','あの子','悔しい','むかつく','許せない']::text[], '視野を広げるための問い →「その時にどうしてほしかったの？」「あなたが戻れるなら、どう行動したいと思う？」。相手を責める話から、本人の願いの話へ角度を変える。'),
  ('T3', '嶋', '来談者中心寄り', 'ask', NULL, 'main', ARRAY['クラス','新しい','慣れ','居場所','友達']::text[], '「こういう困りは今回が初めて？」と聞く。ここで話の進み方が分かれる。'),
  ('T4', '嶋', '来談者中心寄り', 'read', NULL, 'main', ARRAY['いつも','毎回','また','前も']::text[], '繰り返しのパターンがあるなら、新しい環境への適応がゆっくりなタイプかもしれない、という仮説を持つ。'),
  ('T5', '嶋', '来談者中心寄り', 'ask', NULL, 'main', ARRAY['初めて','今回だけ']::text[], '今回が初めてなら、今までと今回で何が違うのかを聞き、適応をしにくくしている要因を探る。'),
  ('T7', '嶋', '来談者中心寄り', 'ask', NULL, 'main', ARRAY['疲れ','朝','電車','部活','塾','忙し','起き']::text[], '通学の距離や時間など、一見関係なさそうな負荷も聞く。しんどさはクラスのことだけが要因とは限らない。'),
  ('T8', '嶋', '来談者中心寄り', 'resp', NULL, 'main', '{}'::text[], '鳥瞰図的に見せる。「クラスのことでいっぱいだったけど、こういう要素もあってのことか」とわかると落ち着いて捉えるきっかけになる。'),
  ('T9', '嶋', '来談者中心寄り', 'ask', NULL, 'main', ARRAY['グループ','みんな','集団','教室']::text[], '同世代の集団という生活を、本人が好ましいものと捉えているか、毎年また始まったと感じているかを見る。'),
  ('CB6', '理', '文献（複数流派）', 'ask', NULL, 'main', ARRAY['性格','自分が悪い','うまくできない','ダメ']::text[], '漠然とした悩みは、日常のどんな場面で何に困っているのかという具体的な問題として聞き取る。'),
  ('BA1', '理', '文献（複数流派）', 'ask', NULL, 'main', ARRAY['やる気','動けない','何もできない']::text[], '主訴を行動の形にする。「やる気が出ない」ではなく「一日中家にいて何もせず過ごす」のように、状況と行動として捉え直す。'),
  ('B1', '理', '文献（複数流派）', 'read', NULL, 'main', ARRAY['何回も','やってみたけど','効かない','無駄']::text[], '問題を解決しようとする努力そのものが問題を維持していることがある。困るほど人はいつもの解決行動にしがみつく。'),
  ('B2', '理', '文献（複数流派）', 'ask', NULL, 'main', '{}'::text[], 'これまでやってみて効かなかった対処を、何を言い何をしたか、具体的な行動として聞き取る。'),
  ('F1', '理', '文献（複数流派）', 'ask', NULL, 'any', ARRAY['もやもや','うまく言えない','わからない','なんとなく']::text[], '言葉にしがたい感覚には、それを思い浮かべるとからだのどのあたりにどんな感じがあるかを聞いてみる。ぴったりくる言葉を一緒に探し、分析せずそのまま受け取る。'),
  ('S1', '理', '文献（複数流派）', 'stance', NULL, 'rapport', ARRAY['別に','勧められ','言われて','相談したいことはない']::text[], 'ビジター型：問題を表明しない、あるいは解決を期待していない。うまくいっていることへの肯定的な言葉を多く返し、来てくれたこと自体をねぎらう。解決へ急がない。'),
  ('S2', '理', '文献（複数流派）', 'stance', NULL, 'main', ARRAY['せいで','あの子が','先生が','親が','どうしようもない','変わってくれない']::text[], 'コンプレイナント型：不満も期待もあるが、自分は被害者で一人では解決できないと感じている。不満に共感したうえで、変わるべきだと感じている人や状況を観察してもらう方向へ。本人に行動を求めない。'),
  ('S3', '理', '文献（複数流派）', 'stance', NULL, 'goal', ARRAY['どうすれば','変わりたい','やってみる','したい']::text[], 'カスタマー型：自分の問題として自ら変化する必要を感じている。ここで初めて行動の話が生きる。'),
  ('S4', '理', '文献（複数流派）', 'stance', NULL, 'any', '{}'::text[], '関わりの型は会話の中で変化する。型が変わったのに対応が前のままだと、途端にずれる。'),
  ('B3', '理', '文献（複数流派）', 'stance', NULL, 'any', '{}'::text[], '一段下がった立場をとる。教えてもらう姿勢でいると、相手は脅かされずに済む。'),
  ('B4', '理', '文献（複数流派）', 'stance', NULL, 'any', '{}'::text[], '相手の言い回しや、どこを強調しているかに価値観と動機が表れる。悲観的な言い方の人に楽観的な励ましを返すと、協力が得られなくなる。'),
  ('Q1', '理', '文献（複数流派）', 'ask', NULL, 'any', '{}'::text[], '開かれた質問は自由に話せるが漠然として答えづらく、思春期の子には不向きな場面もある。閉ざされた質問は答えやすいが、続けると尋問に感じられ防衛的にさせる。組み合わせる。'),
  ('Q3', '理', '文献（複数流派）', 'ask', NULL, 'main', '{}'::text[], '第1層・データを集める問い：事実と、本人にとっての主観的事実を聞く。多用すると尋問のようになる。'),
  ('Q4', '理', '文献（複数流派）', 'ask', NULL, 'main', '{}'::text[], '第2層・診断的な問い：仮説を検証するために聞く。確証的な情報が得られても、仮説はあくまで仮説にとどめる。'),
  ('Q5', '理', '文献（複数流派）', 'ask', NULL, 'goal', '{}'::text[], '第3層・対決的な問い：こちらの見立てや提案で相手の考えに介入する。関係のできぐあい次第では拙速になる。'),
  ('Q6', '理', '文献（複数流派）', 'ask', NULL, 'any', '{}'::text[], '層が上がるほど間合いをはかる必要がある。関係が薄いのに上の層を出すと相手は閉じる。'),
  ('CB5', '理', '文献（複数流派）', 'ask', NULL, 'any', '{}'::text[], '問答で本人の気づきを導く問い方。「何が頭をよぎった？」「他にどう考えられそう？」「もし友達が同じことを言ったら、何て返す？」'),
  ('A1', '理', '文献（複数流派）', 'resp', NULL, 'any', '{}'::text[], '最小限のはげまし。関心を向けて聞いているのか事務的に聞き流されているのかを、相手はとても敏感に感じ取る。'),
  ('A2', '理', '文献（複数流派）', 'resp', NULL, 'rapport', '{}'::text[], 'くり返し。言われたとおりに返すと安心感と伝わった感じが生まれる。ただし全部をおうむ返しにすると逆効果。'),
  ('A3', '理', '文献（複数流派）', 'resp', NULL, 'main', '{}'::text[], '確認。曖昧な話の場面を特定して具体的にしていくと、本人の中でも整理が進む。'),
